import React from 'react';

const teamMembers = [
  {
    name: 'Vaibhav Kharche',
    role: 'Founder and FullStack Development Software Engineer',
    image: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=500&q=60',
  },
  {
    name: 'Rushikesh Kharche',
    role: 'Finance Analyst',
    image: 'https://media.licdn.com/dms/image/v2/D4D03AQEsilObtL-HSw/profile-displayphoto-scale_400_400/B4DZz6abyuGcAk-/0/1773727761992?e=1787788800&v=beta&t=sz2xEFYpHWpzmCVdD03-pNcc5ySFPakm4z92HGeBv7k',
  },
];

export default function Team() {
  return (
    <section id="team">
      <div className="container section-card">
        <div className="text-center mb-5">
          <p className="text-soft">Meet Our Team</p>
          <h2>People behind VAKharche Systems</h2>
          <p className="section-subtitle">A small team combining software engineering and business insight.</p>
        </div>
        <div className="row g-4">
          {teamMembers.map((member) => (
            <div key={member.name} className="col-md-6">
              <div className="d-flex align-items-center gap-4 p-4 rounded-4 bg-white shadow-sm">
                <img src={member.image} alt={member.name} className="rounded-circle" style={{ width: 88, height: 88, objectFit: 'cover' }} />
                <div>
                  <h5 className="mb-1">{member.name}</h5>
                  <p className="mb-0 text-soft">{member.role}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
